#include <bits/stdc++.h>
using namespace std;
int main(){int n; cin>>n;
 vector<long long> x(n), v(n);
 for(auto&a:x)cin>>a; for(auto&a:v)cin>>a;
 long long t; cin>>t;
 bool col=false;
 for(int i=0;i<n&&!col;i++)for(int j=i+1;j<n;j++){
 double d0=(double)(x[j]-x[i]); double dv=(double)(v[i]-v[j]);
 if(d0*dv>0){ double tau=d0/dv; if(tau>0&&tau<=(double)t){col=true;break;} }
 }
 cout<<(col?"COLLIDE":"SAFE")<<"\n"; return 0;}
